SELECT jsonb_build_object('users',count(*),'coherent',coalesce(bool_and(u.revision=0 AND u.privacy_generation=0 AND s.revision=0 AND s.security_generation=CASE WHEN u.id='8a9a4b27-ce71-52f9-aa47-c45f09f71952' THEN 0 ELSE 1 END AND s.user_id=u.id AND u.mutation_transaction_id<>'' AND s.mutation_transaction_id<>''),false)) FROM app.users u JOIN app.user_security_profiles s ON s.user_id=u.id WHERE u.id=ANY(ARRAY['8a9a4b27-ce71-52f9-aa47-c45f09f71952','3950fc46-5cfd-5911-a245-ff5e90e915d3']::uuid[]);
